package com.example.finance.model

data class UserEntity(val id: Long = 0, val name: String, val email: String, val role: UserRole = UserRole.ADMIN, val currencyPreference: String = "LYD", val languagePreference: AppLanguage = AppLanguage.AR, val createdAt: Long = System.currentTimeMillis(), val remoteId: String = "")
data class AccountEntity(val id: Long = 0, val name: String, val type: AccountType, val currency: String = "LYD", val balance: Double = 0.0, val openingBalance: Double = balance, val accountNumberSafe: String = "", val institution: String = "", val isArchived: Boolean = false, val notes: String = "", val colorHex: String = "#D6B56D", val createdAt: Long = System.currentTimeMillis(), val remoteId: String = "")
data class TransactionEntity(val id: Long = 0, val accountId: Long, val type: TransactionType, val amount: Double, val currency: String = "LYD", val category: String, val date: Long = System.currentTimeMillis(), val description: String, val merchant: String = "", val tags: String = "", val notes: String = "", val attachmentUri: String? = null, val isRecurring: Boolean = false, val status: TransactionStatus = TransactionStatus.COMPLETED, val targetAccountId: Long? = null, val remoteId: String = "")
data class TransferEntity(val id: Long = 0, val fromAccountId: Long, val toAccountId: Long, val amount: Double, val fee: Double = 0.0, val currency: String = "LYD", val date: Long = System.currentTimeMillis(), val description: String = "", val reference: String = "", val remoteId: String = "")
data class BudgetEntity(val id: Long = 0, val name: String, val category: String, val period: BudgetPeriod = BudgetPeriod.MONTHLY, val limitAmount: Double, val currency: String = "LYD", val startDate: Long = System.currentTimeMillis(), val endDate: Long = System.currentTimeMillis() + 30L * 24 * 60 * 60 * 1000, val remoteId: String = "")
data class DebtEntity(val id: Long = 0, val name: String, val creditor: String, val principal: Double, val remaining: Double, val interestRate: Double = 0.0, val dueDate: Long = System.currentTimeMillis() + 90L * 24 * 60 * 60 * 1000, val minimumPayment: Double = 0.0, val currency: String = "LYD", val status: DebtStatus = DebtStatus.ACTIVE, val notes: String = "", val direction: String = "i_owe", val remoteId: String = "")
data class DebtPaymentEntity(val id: Long = 0, val debtId: Long, val amount: Double, val date: Long = System.currentTimeMillis(), val notes: String = "", val currency: String = "LYD", val remoteId: String = "")
data class BillEntity(val id: Long = 0, val name: String, val category: String, val amount: Double, val currency: String = "LYD", val dueDate: Long, val isRecurring: Boolean = true, val recurrenceIntervalDays: Int = 30, val isPaid: Boolean = false, val reminderDaysBefore: Int = 3, val remoteId: String = "")
data class SavingsGoalEntity(val id: Long = 0, val name: String, val targetAmount: Double, val currentAmount: Double = 0.0, val currency: String = "LYD", val deadline: Long, val targetMonthlyDeposit: Double = 0.0, val colorHex: String = "#D6B56D", val remoteId: String = "")
data class AssetEntity(val id: Long = 0, val name: String, val type: AssetType, val value: Double, val currency: String = "LYD", val purchaseDate: Long = System.currentTimeMillis(), val notes: String = "", val remoteId: String = "")
data class HouseholdMemberEntity(val id: Long = 0, val name: String, val role: String = "family", val email: String = "", val contributionPercent: Double = 0.0, val monthlyContribution: Double = 0.0, val isActive: Boolean = true, val remoteId: String = "")
data class HouseholdExpenseEntity(val id: Long = 0, val title: String, val amount: Double, val payerMemberId: Long?, val category: String, val currency: String = "LYD", val date: Long = System.currentTimeMillis(), val isSettled: Boolean = false, val isRecurring: Boolean = false, val notes: String = "", val remoteId: String = "")
data class HouseholdBudgetEntity(val id: Long = 0, val name: String, val amount: Double, val currencyCode: String = "LYD", val period: String = "monthly", val startDate: Long = System.currentTimeMillis(), val endDate: Long? = null, val isActive: Boolean = true, val remoteId: String = "")
data class DocumentEntity(val id: Long = 0, val title: String, val type: DocumentType, val fileUri: String = "", val merchant: String = "", val totalAmount: Double = 0.0, val taxAmount: Double = 0.0, val currency: String = "LYD", val date: Long = System.currentTimeMillis(), val notes: String = "", val linkedTransactionId: Long? = null, val remoteId: String = "")
data class NotificationEntity(val id: Long = 0, val title: String, val message: String, val type: NotificationType, val timestamp: Long = System.currentTimeMillis(), val isRead: Boolean = false, val remoteId: String = "")
data class AuditLogEntity(val id: Long = 0, val action: String, val resource: String, val details: String, val userRole: String = "ADMIN", val timestamp: Long = System.currentTimeMillis(), val remoteId: String = "")
